-- Manual opt-in only; not registered in ordinary author startup.
SET search_path TO new_design,public;
CREATE TABLE character_author_capability(contract text PRIMARY KEY CHECK(contract='character_author_v1'),operational boolean NOT NULL DEFAULT false);
INSERT INTO character_author_capability(contract) VALUES('character_author_v1');
CREATE TABLE character_author_trials(
 id uuid PRIMARY KEY REFERENCES ai_tasks(id),book_id uuid NOT NULL REFERENCES books(id),card_id uuid NOT NULL REFERENCES cards(id),
 request_key uuid NOT NULL UNIQUE,request_hash char(64) NOT NULL,input_payload jsonb NOT NULL,source_snapshot jsonb NOT NULL,frozen_plan jsonb NOT NULL,
 step_id uuid NOT NULL UNIQUE REFERENCES ai_task_steps(id),attempt_id uuid NOT NULL UNIQUE REFERENCES ai_task_attempts(id),
 status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','succeeded','stale','failed','ended_unknown')),reply jsonb,output jsonb,
 summary text NOT NULL DEFAULT '原人物谈话结果待核对',created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX character_author_one_running ON character_author_trials(book_id,card_id) WHERE status='running';
CREATE FUNCTION guard_character_author_trial() RETURNS trigger LANGUAGE plpgsql SET search_path TO pg_catalog,new_design,public,pg_temp AS $$
DECLARE task ai_tasks%ROWTYPE; step ai_task_steps%ROWTYPE; attempt ai_task_attempts%ROWTYPE; contract task_contract_versions%ROWTYPE; recipe prompt_recipe_versions%ROWTYPE; manifest context_manifests%ROWTYPE; route model_route_snapshots%ROWTYPE; source jsonb; actual jsonb; item jsonb; cutoff_order integer; versions jsonb; expected_count integer:=0;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'character author original evidence immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['status','reply','output','summary']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','reply','output','summary']) OR OLD.status<>'running' AND NEW IS DISTINCT FROM OLD OR OLD.reply IS NOT NULL AND NEW.reply IS DISTINCT FROM OLD.reply THEN RAISE EXCEPTION 'character author input and reply immutable' USING ERRCODE='23514'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM character_author_capability capability WHERE capability.contract='character_author_v1' AND capability.operational) OR NEW.status<>'running' OR NEW.reply IS NOT NULL OR NEW.output IS NOT NULL THEN RAISE EXCEPTION 'character author trials not enabled' USING ERRCODE='23514'; END IF;
 END IF;
 SELECT * INTO STRICT task FROM ai_tasks WHERE id=NEW.id AND book_id=NEW.book_id;
 SELECT * INTO STRICT step FROM ai_task_steps WHERE id=NEW.step_id AND task_id=NEW.id AND current_attempt_id=NEW.attempt_id;
 SELECT * INTO STRICT attempt FROM ai_task_attempts WHERE id=NEW.attempt_id AND task_id=NEW.id AND step_id=NEW.step_id;
 SELECT * INTO STRICT contract FROM task_contract_versions WHERE id=attempt.task_contract_version_id;
 SELECT * INTO STRICT recipe FROM prompt_recipe_versions WHERE id=attempt.prompt_recipe_version_id;
 SELECT * INTO STRICT manifest FROM context_manifests WHERE id=attempt.context_manifest_id;
 SELECT * INTO STRICT route FROM model_route_snapshots WHERE id=attempt.model_route_snapshot_id;
 source:=NEW.source_snapshot;
 IF NOT COALESCE(task.source_kind='character_author' AND task.source_id=NEW.id AND task.request_idempotency_key=NEW.request_key::text AND task.request_hash=NEW.request_hash AND task.task_contract_version_id=contract.id AND step.step_key='character_author' AND step.max_attempts=1 AND attempt.attempt_number=1 AND attempt.input_hash=NEW.frozen_plan->>'inputHash' AND attempt.output_schema_version=NEW.frozen_plan->>'outputSchemaVersion' AND contract.status='published' AND contract.task_group='character_dialogue' AND contract.budget_policy->>'assetId'='new_design.character.author_conversation' AND contract.retry_policy='{"maxAttempts":1,"automaticRetry":false}'::jsonb AND recipe.status='published' AND recipe.id=contract.prompt_recipe_version_id AND recipe.variables_schema->'const'=contract.input_schema->'const' AND contract.input_schema->'const'=NEW.frozen_plan->'promptInput' AND NEW.frozen_plan->'promptInput'->>'contract'='character_author_v1' AND NEW.frozen_plan->'promptInput'->'input'=NEW.input_payload AND NEW.frozen_plan->'promptInput'->'source'=source AND manifest.book_id=NEW.book_id AND manifest.task_contract_version_id=contract.id AND manifest.prompt_recipe_version_id=recipe.id AND manifest.model_route_snapshot_id=route.id AND manifest.source_set_hash=source->>'hash' AND route.snapshot_hash=NEW.frozen_plan->>'snapshotHash' AND route.retry_policy->>'maxRetries'='0' AND NEW.frozen_plan->'route'->'fallbacks'='[]'::jsonb AND NEW.input_payload->>'requestKey'=NEW.request_key::text AND NEW.input_payload->>'bookId'=NEW.book_id::text AND NEW.input_payload->>'cardId'=NEW.card_id::text AND NEW.input_payload->>'sourceHash'=source->>'hash' AND source->>'bookId'=NEW.book_id::text AND source->>'cardId'=NEW.card_id::text AND source->'cutoffBodyVersionId'=NEW.input_payload->'cutoffBodyVersionId',false) THEN RAISE EXCEPTION 'character author frozen contract mismatch' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF task.status<>'running' OR step.status<>'running' OR attempt.status<>'running' OR NEW.input_payload->>'kind' NOT IN ('conversation','scene_analysis') OR jsonb_typeof(NEW.input_payload->'historyKeys')<>'array' THEN RAISE EXCEPTION 'character author original claim mismatch' USING ERRCODE='23514'; END IF;
  SELECT jsonb_build_object('id',id,'name',name,'description',description,'revision',revision) INTO actual FROM books WHERE id=NEW.book_id AND status='active';
  IF actual IS NULL OR actual IS DISTINCT FROM source->'data'->'book' THEN RAISE EXCEPTION 'character author book source mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('requestKey',prior.request_key,'kind',prior.input_payload->>'kind','message',prior.input_payload->>'message','output',prior.output) ORDER BY prior.created_at,prior.id),'[]'::jsonb),COALESCE(jsonb_agg(prior.request_key ORDER BY prior.created_at,prior.id),'[]'::jsonb) INTO actual,versions FROM character_author_trials prior WHERE prior.book_id=NEW.book_id AND prior.card_id=NEW.card_id AND prior.status='succeeded' AND prior.source_snapshot->>'hash'=source->>'hash';
  IF jsonb_array_length(versions)>100 OR versions IS DISTINCT FROM NEW.input_payload->'historyKeys' OR actual IS DISTINCT FROM NEW.frozen_plan->'promptInput'->'history' THEN RAISE EXCEPTION 'character author causal history mismatch' USING ERRCODE='23514'; END IF;
  SELECT jsonb_build_object('id',card.id,'versionId',version.id,'title',version.title,'typeVersionId',version.type_version_id,'values',version.values,'fields',spec.fields,'localFields',COALESCE((SELECT jsonb_agg(jsonb_build_object('definitionId',definition.id,'versionId',local_spec.id,'field',local_spec.field_schema,'value',local.value) ORDER BY definition.field_key) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id JOIN field_definition_versions local_spec ON local_spec.id=local.field_definition_version_id AND local_spec.field_definition_id=definition.id WHERE local.card_version_id=version.id),'[]'::jsonb)) INTO actual FROM cards card JOIN books book ON book.space_id=card.space_id AND book.id=NEW.book_id AND book.status='active' JOIN card_types type ON type.id=card.card_type_id AND type.type_key='character' JOIN card_versions version ON version.id=card.current_version_id AND version.card_id=card.id JOIN card_type_versions spec ON spec.id=version.type_version_id AND spec.card_type_id=type.id WHERE card.id=NEW.card_id AND card.status='active';
  IF actual IS NULL OR actual IS DISTINCT FROM source->'data'->'profile' THEN RAISE EXCEPTION 'character author profile source mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',relation.id,'versionId',version.id,'revision',version.revision,'properties',version.properties,'type',jsonb_build_object('id',type.id,'name',type.name,'direction',type.direction,'fields',type.properties_schema,'updatedAt',to_char(type.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),'sourceId',endpoint_source.card_id,'sourceVersionId',endpoint_source.id,'sourceTitle',endpoint_source.title,'targetId',endpoint_target.card_id,'targetVersionId',endpoint_target.id,'targetTitle',endpoint_target.title) ORDER BY relation.id),'[]'::jsonb) INTO actual FROM card_relations relation JOIN books book ON book.space_id=relation.space_id AND book.id=NEW.book_id JOIN relation_types type ON type.id=relation.relation_type_id AND type.status='published' JOIN card_relation_versions version ON version.id=relation.current_version_id AND version.card_relation_id=relation.id AND version.status='active' JOIN card_versions endpoint_source ON endpoint_source.id=version.source_card_version_id AND endpoint_source.card_id=relation.source_card_id JOIN card_versions endpoint_target ON endpoint_target.id=version.target_card_version_id AND endpoint_target.card_id=relation.target_card_id WHERE relation.status='active' AND (relation.source_card_id=NEW.card_id OR relation.target_card_id=NEW.card_id);
  IF actual IS DISTINCT FROM source->'data'->'relations' OR jsonb_array_length(actual)>200 OR EXISTS(SELECT 1 FROM card_relations relation JOIN books book ON book.space_id=relation.space_id AND book.id=NEW.book_id WHERE relation.status='active' AND (relation.source_card_id=NEW.card_id OR relation.target_card_id=NEW.card_id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual) AS relation_items(relation_item) WHERE relation_items.relation_item->>'id'=relation.id::text)) THEN RAISE EXCEPTION 'character author complete current setting relations mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.input_payload->>'cutoffBodyVersionId' IS NULL THEN
   IF jsonb_array_length(source->'data'->'chapters')<>0 OR EXISTS(SELECT 1 FROM chapter_documents WHERE book_id=NEW.book_id AND status='active' AND adopted_version_id IS NOT NULL) THEN RAISE EXCEPTION 'character author must select occurred chapter range' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT document.logical_order INTO STRICT cutoff_order FROM chapter_documents document JOIN chapter_body_versions body ON body.id=document.adopted_version_id AND body.chapter_document_id=document.id AND body.archived_at IS NULL WHERE document.book_id=NEW.book_id AND document.status='active' AND body.id=(NEW.input_payload->>'cutoffBodyVersionId')::uuid;
   SELECT COALESCE(jsonb_agg(jsonb_build_object('documentId',document.id,'bodyVersionId',body.id,'title',document.title,'order',document.logical_order,'content',body.content,'contentHash',body.content_hash) ORDER BY document.logical_order,document.id),'[]'::jsonb) INTO actual FROM chapter_documents document JOIN chapter_body_versions body ON body.id=document.adopted_version_id AND body.chapter_document_id=document.id AND body.archived_at IS NULL WHERE document.book_id=NEW.book_id AND document.status='active' AND document.logical_order<=cutoff_order;
   IF actual IS DISTINCT FROM source->'data'->'chapters' THEN RAISE EXCEPTION 'character author occurred body versions mismatch' USING ERRCODE='23514'; END IF;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('stableId',initial.id,'versionId',version.id,'subjectKind',initial.subject_kind,'subjectId',initial.subject_id,'fieldKey',initial.state_key,'value',version.value_json,'kind','initial') ORDER BY initial.subject_kind,initial.subject_id,initial.state_key),'[]'::jsonb) INTO actual FROM entity_initial_states initial JOIN entity_initial_state_versions version ON version.id=initial.current_version_id AND version.initial_state_id=initial.id WHERE initial.book_id=NEW.book_id AND ((initial.subject_kind='card' AND initial.subject_id=NEW.card_id) OR (initial.subject_kind='relation' AND EXISTS(SELECT 1 FROM jsonb_array_elements(source->'data'->'relations') relation WHERE relation->>'id'=initial.subject_id::text)));
  SELECT actual||COALESCE(jsonb_agg(jsonb_build_object('stableId',change.id,'versionId',change.id,'subjectKind',change.subject_kind,'subjectId',change.subject_id,'fieldKey',change.state_key,'value',change.after_json,'chapterOrder',document.logical_order,'sequence',change.sequence::text,'kind','change') ORDER BY document.logical_order,change.sequence,change.id),'[]'::jsonb) INTO actual FROM state_changes change JOIN chapter_documents document ON document.id=change.chapter_document_id AND document.book_id=change.book_id AND document.status='active' AND document.adopted_version_id=change.body_version_id WHERE change.book_id=NEW.book_id AND ((change.subject_kind='card' AND change.subject_id=NEW.card_id) OR (change.subject_kind='relation' AND EXISTS(SELECT 1 FROM jsonb_array_elements(source->'data'->'relations') relation WHERE relation->>'id'=change.subject_id::text))) AND change.status='active' AND document.logical_order<=cutoff_order;
  IF actual IS DISTINCT FROM source->'data'->'states' THEN RAISE EXCEPTION 'character author complete state sources mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('versionId',change.id,'stableId',change.proposal_id,'claimId',change.claim_id,'stance',change.stance,'predicate',claim.predicate,'value',claim.value_json,'chapterOrder',document.logical_order) ORDER BY document.logical_order,change.id),'[]'::jsonb) INTO actual FROM knowledge_state_changes change JOIN knowledge_state_proposals proposal ON proposal.id=change.proposal_id AND proposal.book_id=change.book_id AND proposal.status='confirmed' AND proposal.confirmed_change_id=change.id JOIN knowledge_state_proposal_versions version ON version.id=change.proposal_version_id AND version.proposal_id=proposal.id JOIN epistemic_claims claim ON claim.id=change.claim_id AND claim.book_id=change.book_id JOIN chapter_documents document ON document.id=version.chapter_document_id AND document.book_id=change.book_id AND document.status='active' AND document.adopted_version_id=version.body_version_id WHERE change.book_id=NEW.book_id AND change.holder_card_id=NEW.card_id AND change.holder_kind='character' AND change.status='active' AND document.logical_order<=cutoff_order;
  IF actual IS DISTINCT FROM source->'data'->'knowledge' THEN RAISE EXCEPTION 'character author complete confirmed knowledge mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(version_id ORDER BY first_order),'[]'::jsonb) INTO versions FROM (SELECT version_id,min(ord) first_order FROM jsonb_array_elements_text(jsonb_build_array(source->'data'->'profile'->'versionId',source->'data'->'profile'->'typeVersionId')||(SELECT COALESCE(jsonb_agg(local->'versionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'profile'->'localFields') WITH ORDINALITY AS locals(local,ord))||(SELECT COALESCE(jsonb_agg(versions.version_id ORDER BY ord,versions.local_order),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'relations') WITH ORDINALITY AS relations(relation,ord) CROSS JOIN LATERAL (VALUES (relation->'versionId',0),(relation->'sourceVersionId',1),(relation->'targetVersionId',2)) AS versions(version_id,local_order))||(SELECT COALESCE(jsonb_agg(chapter->'bodyVersionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'chapters') WITH ORDINALITY AS chapters(chapter,ord))||(SELECT COALESCE(jsonb_agg(state->'versionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'states') WITH ORDINALITY AS states(state,ord))||(SELECT COALESCE(jsonb_agg(knowledge->'versionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'knowledge') WITH ORDINALITY AS knowledge_sources(knowledge,ord))) WITH ORDINALITY AS cited(version_id,ord) GROUP BY version_id) deduplicated;
  IF versions IS DISTINCT FROM source->'versionIds' THEN RAISE EXCEPTION 'character author exact citation set mismatch' USING ERRCODE='23514'; END IF;
  FOR item IN SELECT DISTINCT expected.item FROM (SELECT jsonb_build_object('kind','card_version','sourceType','card_version','stableId',NEW.card_id,'versionId',source->'data'->'profile'->>'versionId') AS item UNION ALL SELECT jsonb_build_object('kind','card_relation','sourceType','card_relation','stableId',relation->>'id','versionId',relation->>'versionId') FROM jsonb_array_elements(source->'data'->'relations') relation UNION ALL SELECT jsonb_build_object('kind','card_version','sourceType','card_version','stableId',relation->>'sourceId','versionId',relation->>'sourceVersionId') FROM jsonb_array_elements(source->'data'->'relations') relation UNION ALL SELECT jsonb_build_object('kind','card_version','sourceType','card_version','stableId',relation->>'targetId','versionId',relation->>'targetVersionId') FROM jsonb_array_elements(source->'data'->'relations') relation UNION ALL SELECT jsonb_build_object('kind','chapter_body_version','sourceType','body_version','stableId',chapter->>'documentId','versionId',chapter->>'bodyVersionId') FROM jsonb_array_elements(source->'data'->'chapters') chapter UNION ALL SELECT jsonb_build_object('kind',CASE WHEN state->>'kind'='initial' THEN 'entity_initial_state' ELSE 'state_change' END,'sourceType',CASE WHEN state->>'kind'='initial' THEN 'entity_initial_state' ELSE 'state_change' END,'stableId',state->>'stableId','versionId',state->>'versionId') FROM jsonb_array_elements(source->'data'->'states') state UNION ALL SELECT jsonb_build_object('kind','knowledge_state_change','sourceType','knowledge_state_change','stableId',knowledge->>'stableId','versionId',knowledge->>'versionId') FROM jsonb_array_elements(source->'data'->'knowledge') knowledge) expected LOOP
   expected_count:=expected_count+1;
   IF NOT EXISTS(SELECT 1 FROM context_manifest_entries entry CROSS JOIN LATERAL resolve_dependency_resource(item->>'kind',(item->>'stableId')::uuid,(item->>'versionId')::uuid) resolved WHERE entry.manifest_id=manifest.id AND entry.source_type=item->>'sourceType' AND entry.stable_object_id=(item->>'stableId')::uuid AND entry.exact_version_id=(item->>'versionId')::uuid AND entry.content_role='required' AND entry.transform_status='full' AND entry.content_hash=resolved.resolved_hash AND resolved.resolved_book_id=NEW.book_id) THEN RAISE EXCEPTION 'character author manifest exact source missing' USING ERRCODE='23514'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM context_manifest_entries WHERE manifest_id=manifest.id)<>expected_count THEN RAISE EXCEPTION 'character author unexpected manifest source' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.reply IS NOT NULL AND NOT COALESCE(NEW.reply->'output'->>'bookId'=NEW.book_id::text AND NEW.reply->'output'->>'cardId'=NEW.card_id::text AND NEW.reply->'output'->>'sourceHash'=source->>'hash' AND NEW.reply->'execution'->>'routeSnapshotId'=route.id::text AND NEW.reply->'execution'->>'routeSnapshotHash'=route.snapshot_hash AND NEW.reply->'execution'->>'provider'=route.provider AND NEW.reply->'execution'->>'model'=route.model AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.reply->'execution'->'attempts') trace WHERE trace->>'status'='succeeded' AND trace->>'requestSent'='true' AND trace->>'responseReceived'='true'),false) THEN RAISE EXCEPTION 'character author reply original execution mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.reply IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.reply->'output'->'sourceVersionIds') AS cited(version_id) WHERE NOT ((source->'versionIds') ? cited.version_id)) THEN RAISE EXCEPTION 'character author reply cites foreign version' USING ERRCODE='23514'; END IF;
 IF NEW.status='running' AND (NEW.output IS NOT NULL OR task.status<>'running' OR step.status<>'running' OR attempt.status<>'running') THEN RAISE EXCEPTION 'character author running ledger mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status IN ('succeeded','stale') AND (NEW.reply IS NULL OR NEW.output IS DISTINCT FROM NEW.reply->'output' OR task.status<>'succeeded' OR step.status<>'succeeded' OR attempt.status<>'succeeded') OR NEW.status='failed' AND (NEW.output IS NOT NULL OR task.status<>'failed' OR step.status<>'failed' OR attempt.status<>'failed') OR NEW.status='ended_unknown' AND (NEW.reply IS NOT NULL OR NEW.output IS NOT NULL OR task.status<>'cancelled' OR step.status<>'cancelled' OR attempt.status<>'discarded') THEN RAISE EXCEPTION 'character author terminal ledger mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER character_author_trial_guard BEFORE INSERT OR UPDATE OR DELETE ON character_author_trials FOR EACH ROW EXECUTE FUNCTION guard_character_author_trial();
